from gql import Client
from gql.transport import Transport
from graphql import ExecutionResult
from gql.transport.exceptions import TransportQueryError

# Simulate the exact scenario from the issue: 429 response with dict errors
class RateLimitTransport(Transport):
    def execute(self, document, *args, **kwargs):
        return ExecutionResult(
            errors={'message': 'Rate limit exceeded', 'retry-after': 30},
            data=None
        )

client = Client(transport=RateLimitTransport(), fetch_schema_from_transport=True)

try:
    with client:
        pass
except KeyError as e:
    print(f'FAIL: KeyError still occurs: {e}')
except TransportQueryError as e:
    print('SUCCESS: Proper TransportQueryError raised instead of KeyError')
    print(f'Error message: {str(e)[:80]}...')
